import {renderWhatif,renderRebalance,renderRecovery,renderSettings,mountDecisionScenes} from './scenes-decisions.js';
import {renderWeek,renderSemester,mountCalendarScenes} from './scenes-calendar.js';
import {renderInbox,renderReview,mountInboxScenes} from './scenes-inbox.js';
import {welcomeRoute,renderWelcome,renderGuide,onboardingAction} from './onboarding.js';
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',semester:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12M15 9v12M3 15h18"/>',inbox:'<path d="M4 4h16l2 10v6H2v-6zM2 14h6l2 3h4l2-3h6"/>',spark:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z"/>',balance:'<path d="M4 7h16M4 17h16M8 4v6M16 14v6"/>',leaf:'<path d="M20 3C8 2 2 9 5 16s16 5 15-13ZM5 20 16 9"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="#0b0e13"/><circle cx="16" cy="17" r="3" fill="#0b0e13"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-6 0" transform="translate(0 0) scale(.95)"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevron:'<path d="m9 5 7 7-7 7"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>',chat:'<path d="M21 14a4 4 0 0 1-4 4H9l-6 4V6a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={moved:false,requested:false,confirmed:false,reviewed:false,done:false,recovery:false,shift:2,selectedWeek:4,settings:{focus:'14:00',rest:'23:00',session:'120',accent:'lime',mental:'High',physical:'Moderate',social:'Moderate',admin:'Light'},uploaded:[],note:''};
let lastState=null,toastTimer;
let motionPaused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let chapter=0;
let sceneCleanup=()=>{};
function sceneContext(){return {state,margin,workHours,availableHours,icon,link,button,toast,modal,shell,hasUndo:!!lastState};}
const navs=[['week','calendar','My week'],['inbox','inbox','Add stuff'],['rebalance','balance','Make room']];
const page=()=>location.hash.slice(1)||'week';
const availableHours=()=>8-(state.done?2:0);
const workHours=()=>10-(state.moved?1:0)-(state.confirmed?2:0)-(state.done?2:0);
const margin=()=>availableHours()-workHours();
const link=(target,label,cls='button',ic='arrow')=>`<a class="${cls}" href="#${target}">${label}${icon(ic)}</a>`;
const button=(act,label,cls='button',ic='')=>`<button class="${cls}" data-action="${act}">${ic?icon(ic):''}${label}</button>`;
function shell(){
  const restoreFocus=document.querySelector('#app')?.contains(document.activeElement);
  sceneCleanup();
  const p=welcomeRoute(page());
  document.body.dataset.view=p;
  document.body.dataset.room=margin()>0?'open':'tight';
  document.body.classList.toggle('calm-app',p!=='home');
  const c=sceneContext();
  const more=`<details class="app-menu"><summary>More</summary><div class="app-menu-items"><a href="#semester">${icon('semester')}Semester overview</a><a href="#whatif">${icon('spark')}Test a new commitment</a><a href="#recovery">${icon('leaf')}Take a break</a><a href="#settings">${icon('settings')}Preferences</a><hr>${button('tour','Quick tour','','spark')}${button('about','About this demo','','inbox')}<a href="#home">${icon('arrow')}The idea behind Margin</a></div></details>`;
  document.querySelector('#app').innerHTML=`<div class="shell ${p==='home'?'at-home':p==='start'?'at-start':''}">${p==='home'?'<div class="ambient" aria-hidden="true"><img src="/assets/margin-portal.png" alt=""></div>':''}<header class="studio-header"><a class="studio-brand" href="${p==='home'?'#home':'#week'}" aria-label="Margin home">margin<span>✳</span></a><nav class="studio-nav" aria-label="Main navigation">${navs.map(([id,ic,label])=>{const active=p===id||(p==='review'&&id==='inbox');return `<a href="#${id}" data-nav="${id}" class="${active?'active':''}" ${active?'aria-current="page"':''}>${label}</a>`}).join('')}</nav><div class="studio-actions">${p==='home'?`<button class="motion-button" data-action="motion" aria-label="Pause animation">${icon('moon')}<span>Pause motion</span></button>${link('start','Get started','button primary small','arrow')}`:`<button class="motion-button" data-action="motion" aria-label="Pause animation">${icon('moon')}<span>Pause motion</span></button>${more}`}</div></header>${p==='home'?home():`<main class="main" id="main" tabindex="-1">${renderGuide(c,p)}${({start:()=>renderWelcome(c),week:()=>renderWeek(c),semester:()=>renderSemester(c),inbox:()=>renderInbox(c),review:()=>renderReview(c),whatif:()=>renderWhatif(c),rebalance:()=>renderRebalance(c),recovery:()=>renderRecovery(c),settings:()=>renderSettings(c)}[p]||(()=>renderWeek(c)))()}</main><footer class="planner-footer"><span>Sample data · Changes stay in this demo</span><div><button class="inline-link" data-action="tour">Quick tour</button><button class="inline-link" data-action="about">About the prototype</button></div></footer>`}</div>`;
  document.title=`Margin — ${p==='home'?'Make room for life':p==='start'?'Welcome':navs.find(x=>x[0]===p)?.[2]||p.charAt(0).toUpperCase()+p.slice(1)}`;
  bindFields();
  const cleanups=[mountDecisionScenes(c),mountCalendarScenes(c),mountInboxScenes(c)];
  sceneCleanup=()=>cleanups.forEach(fn=>typeof fn==='function'&&fn());
  setupMotion();
  if(restoreFocus)document.querySelector('#main')?.focus({preventScroll:true});
}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
function modal(title,text,extra=''){const d=document.querySelector('#modal');d.innerHTML=`<div class="dialog-top"><span>Margin / Demo workspace</span><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><h2 id="modal-title">${esc(title)}</h2><p>${text}</p>${extra||button('close','Got it','button primary wide')}`;d.setAttribute('aria-labelledby','modal-title');d.showModal()}
function snapshot(){lastState={moved:state.moved,requested:state.requested,confirmed:state.confirmed,done:state.done}}
document.addEventListener('click',e=>{
  const a=e.target.closest('[data-action]')?.dataset.action;
  if(a&&onboardingAction(a,sceneContext())){e.preventDefault();e.stopImmediatePropagation();return;}
  if(a==='move-groceries-only'){snapshot();state.moved=true;shell();toast('Groceries moved to Saturday. One more hour freed before Friday.');e.preventDefault();e.stopImmediatePropagation();return;}
  if(!e.target.closest('.app-menu'))document.querySelector('.app-menu')?.removeAttribute('open');
},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.app-menu')?.removeAttribute('open');});
function bindFields(){document.querySelector('#life-note')?.addEventListener('input',e=>state.note=e.target.value);document.querySelector('#local-file')?.addEventListener('change',e=>{if(e.target.files[0]){state.uploaded.push(e.target.files[0].name);shell();toast('File attached locally. This UI prototype does not extract its contents.')}});document.querySelector('#shift-hours')?.addEventListener('change',e=>{state.shift=Number(e.target.value);shell()});document.querySelector('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();Object.assign(state.settings,Object.fromEntries(new FormData(e.target)));toast('Preferences saved for this demo session. Calendar times stay in the sample scenario.');});}
document.addEventListener('click',async e=>{const event=e.target.closest('[data-event]');if(event){const name=event.dataset.event;modal(name,'This is a synthetic calendar item. Fixed events keep their original time. Proposed focus blocks illustrate where the report work could fit. Friday’s noon marker is a deadline, not a work session.',link('rebalance','Review my plan','button primary wide'));return}const wk=e.target.closest('[data-week]');if(wk){state.selectedWeek=Number(wk.dataset.week);shell();return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='close'){document.querySelector('#modal').close();return}if(a==='about'){modal('A working preview of the idea','Explore the calendar, imports, what-if simulation and approval flow with synthetic student data. AI extraction, live calendar sync and external messages are planned integrations. This prototype does not connect to accounts, send messages or diagnose burnout.',`<div class="row wrap">${link('inbox','Start the story','button primary','arrow')}<a class="button ghost" href="#start">Take the quick tour</a></div>`);return}if(a==='sample-syllabus'){location.hash='review';return}if(a==='sample-calendar'){modal('Calendar sample','Data structures: Tuesday 9–11 AM. Lab: Wednesday 10 AM–noon. Algorithms: Thursday 9–11 AM. These are fixed demo commitments. Live Google Calendar and .ics import are planned.',link('week','See the sample calendar','button primary wide'));return}if(a==='sample-roster'){modal('Shift roster sample','Wednesday 6–8 PM and Friday 3–5 PM are fixed café shifts in this demo. A live import would review the image, dates and time zone before adding anything.',link('week','See the sample shifts','button primary wide'));return}if(a==='attach'){document.querySelector('#local-file').click();return}if(a==='paste'){document.querySelector('#life-note').focus();return}if(a==='review-note'){if(!state.note.trim()){toast('Add a note first, or choose a sample above.');return}modal('Your note, captured',`“${esc(state.note)}”<br><br>This prototype keeps your note locally. Continue into a labelled sample to preview the AI review experience.`,link('review','Explore sample review','button primary wide'));return}if(a==='confirm-import'){if(!document.querySelector('#review-check').checked){toast('Confirm that you checked the source first.');return}if(document.querySelector('#effort').value!=='6'||document.querySelector('#deadline-time').value!=='12:00'){modal('Alternative inputs need a live planner','The current demo story uses 6h of work due Friday at noon. We have not applied your alternative values to the sample calendar. Continue with the demo values or return to edit.',`<div class="row">${button('continue-sample','Use sample values','button primary')}${button('close','Keep editing','button ghost')}</div>`);return}state.reviewed=true;location.hash='week';toast('Sample added. Here’s how it fits into your week.');return}if(a==='continue-sample'){state.reviewed=true;document.querySelector('#modal').close();location.hash='week';return}if(a==='apply-plan'){snapshot();const move=document.querySelector('#move-groceries');const help=document.querySelector('#request-help');if(!move.checked&&!help.checked){toast('Choose a suggestion first. Nothing has changed.');return}if(move.checked)state.moved=true;if(help.checked)state.requested=true;shell();toast(state.requested&&!state.confirmed?'Changes applied. Handover pending: outreach still counts as your work.':'Selected changes applied in the demo.');return}if(a==='confirm-handover'){snapshot();state.confirmed=true;shell();toast('Demo handover confirmed. The 2h outreach task is now off your workload.');return}if(a==='undo'){if(lastState){Object.assign(state,lastState);lastState=null;shell();toast('Last plan change undone.')}return}if(a==='complete'){state.done=!state.done;shell();toast(state.done?'2h completed. Remaining work updated.':'Task restored to remaining work.');return}if(a==='copy-reply'){try{await navigator.clipboard.writeText('I can’t take the full shift before Friday. Is a weekend shift available instead?');toast('Reply copied. Nothing has been sent.')}catch{modal('Suggested reply','“I can’t take the full shift before Friday. Is a weekend shift available instead?”')}return}if(a==='keep-rest'){state.recovery=true;shell();toast('Thursday’s walk stays protected.');return}if(a.startsWith('recovery-')){const labels={walk:'A short walk',friend:'A low-key catch-up',quiet:'Some quiet time'};modal(labels[a.split('-')[1]],'Choose the kind of recovery that feels right to you. In the full build, you can preview a time and approve the calendar change. Nothing has been scheduled automatically.');return}if(a==='reset'){modal('Reset this demo?', 'This clears only the changes, local filenames and notes you entered in this browser session. No external calendar or file is affected.',`<div class="row">${button('confirm-reset','Reset demo','button primary')}${button('close','Keep my changes','button ghost')}</div>`);return}if(a==='confirm-reset'){location.hash='week';location.reload();}});
document.addEventListener('click',e=>{if(e.target.closest('dialog a'))document.querySelector('#modal').close();if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();}});
function home(){const words=['Your semester','Your café shifts','Your committee','Your deadlines','Your people','Your downtime'];return `<main class="film-home" id="main" tabindex="-1"><section class="film-stage"><div class="film-media" aria-hidden="true"><img src="/assets/margin-portal.png" alt=""><video muted loop playsinline preload="metadata" ${motionPaused?'':'autoplay'} poster="/assets/margin-motion-poster.jpg"><source src="/assets/margin-motion-web.mp4" type="video/mp4"></video><div class="video-wash"></div></div><div class="film-copy"><div class="film-kicker"><i></i>ONE LIFE. A LITTLE MORE SPACE.</div><h1 class="film-title"><span><span>MAKE ROOM.</span></span><span><span>FOR LIFE.</span></span></h1><p>Your semester, shifts and everything in between.<br>A calendar that helps you carry it all<br>without filling every last minute.</p><div class="film-cta">${link('start','Get started','button primary','arrow')}<button class="text-button" data-action="experience">${icon('spark')}Explore the idea</button></div></div><div class="orbit-label">Your life, coming together</div><div class="orbit-chips"><a href="#review" class="orbit-chip one">${icon('file')}<span><strong>Course report</strong><small>Friday, 12 PM · 6h to prepare</small></span></a><a href="#whatif" class="orbit-chip two">${icon('clock')}<span><strong>Another café shift?</strong><small>See what saying yes would cost</small></span></a><a href="#rebalance" class="orbit-chip three">${icon('people')}<span><strong>Committee outreach</strong><small>2h could be shared</small></span></a></div><div class="film-bottom"><div class="film-statblock"><p class="film-caption">Alex’s demo week</p><div class="film-stat">${workHours()}h<span>of work / ${availableHours()}h available</span></div></div><div class="film-statblock"><p class="film-caption">The room we’re looking for</p><div class="film-stat"><span class="negative" style="font:inherit">${margin()>0?'+':''}${margin()}h</span><span>${margin()<0?'needs another solution':'of actual margin'}</span></div></div><div class="film-statblock"><button class="text-button film-scroll" data-action="experience">Scroll into your life ${icon('arrow')}</button><p style="font-size:9px;color:#67747f;margin-top:11px">Interactive UI prototype · uc-7-9</p></div></div></section><div class="film-marquee" aria-hidden="true"><div class="marquee-track">${[...words,...words,...words,...words].map(w=>`<span>${w}</span><i>✳</i>`).join('')}</div></div><section class="experience-section" id="experience"><p class="eyebrow">A STUDENT LIFE DOESN’T ARRIVE ORGANISED</p><h2>All those separate things.<br><span>One life carrying them.</span></h2><div class="experience-grid"><div class="experience-steps">${[['Drop it all in','A syllabus. A screenshot. A committee message. Start with the sources you already have.'],['See the actual load','The deadline is only the visible part. Bring the preparation and your real availability into view.'],['Find your breathing room','Move a flexible errand. Ask for help. See what changes, then decide.']].map(([t,p],i)=>`<button class="experience-step ${chapter===i?'active':''}" data-chapter="${i}" aria-pressed="${chapter===i}"><span class="number">0${i+1}</span><span><strong>${t}</strong><p>${p}</p></span>${icon('arrow')}</button>`).join('')}</div><div class="experience-visual" id="experience-preview" aria-live="polite">${chapterPreview()}</div></div></section><section class="life-manifesto"><p class="eyebrow">AMBITION NEEDS A LITTLE SPACE</p><h2>More living.<br><em>Less overload.</em></h2><p>Margin is built around the whole student life, including the part that never makes it onto a timetable.</p>${link('inbox','Bring your life in','button primary','arrow')}</section><footer class="film-footer"><a class="studio-brand" href="#home">margin<span>✳</span></a><span>CodeNection 2026<br>Stress & Workload Manager · uc-7-9</span><div><a href="#start">Try the prototype ↗</a><a href="#settings">Your controls ↗</a></div></footer></main>`}
function chapterPreview(){if(chapter===0)return `<div class="experience-demo"><p class="eyebrow">01 / LIFE INBOX · SAMPLE INPUTS</p><h3>Messy is a perfectly good start.</h3>${[['file','Semester syllabus.pdf','Assessments and due dates','Review'],['clock','September shift roster','Fixed work commitments','Review'],['chat','Committee group chat','“Can you handle outreach?”','Review']].map(([i,t,d,s])=>`<div class="demo-file">${icon(i)}<div><strong>${t}</strong><small>${d}</small></div><span>${s}</span></div>`).join('')}<div class="demo-actions">${link('inbox','Try the Life Inbox','button primary small','arrow')}</div></div>`;if(chapter===1)return `<div class="experience-demo"><p class="eyebrow">02 / THE WHOLE LOAD · DEMO SCENARIO</p><h3>The hours tell a different story.</h3><div class="demo-capacity">10 <small>/ 8h</small></div><div class="demo-hours">${Array.from({length:10},()=>'<i></i>').join('')}</div><p class="demo-explain">6h for the report. 3h for committee work. 1h for groceries. Only 8h fit before Friday noon.</p>${link('whatif','Test one more commitment','button primary small','spark')}</div>`;return `<div class="experience-demo"><p class="eyebrow">03 / A POSSIBLE PLAN · AFTER AGREEMENT</p><div class="demo-success">+1h</div><h3>That’s your margin.</h3><p class="demo-explain">Groceries move to Saturday. A committee member confirms a 2h handover. Your 10h becomes 7h of work before Friday.</p><div class="demo-file">${icon('shield')}<div><strong>Sleep and recovery stay protected</strong><small>Pending requests still count until confirmed</small></div></div><div class="demo-actions">${link('rebalance','Choose the changes','button primary small','arrow')}</div></div>`}
function setupMotion(){document.body.classList.toggle('motion-paused',motionPaused);document.querySelectorAll('.motion-button').forEach(b=>{b.setAttribute('aria-label',motionPaused?'Resume animation':'Pause animation');b.innerHTML=`${icon(motionPaused?'spark':'moon')}<span>${motionPaused?'Resume motion':'Pause motion'}</span>`});document.querySelectorAll('video').forEach(v=>{if(motionPaused||(v.classList.contains('atmosphere-film')&&page()==='home'))v.pause();else v.play().catch(()=>{});});}
document.addEventListener('click',e=>{const step=e.target.closest('[data-chapter]');if(step){chapter=Number(step.dataset.chapter);document.querySelectorAll('[data-chapter]').forEach(b=>{const active=Number(b.dataset.chapter)===chapter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('#experience-preview').innerHTML=chapterPreview();return}const act=e.target.closest('[data-action]')?.dataset.action;if(act==='motion'){motionPaused=!motionPaused;setupMotion()}if(act==='experience'){document.querySelector('#experience')?.scrollIntoView({behavior:motionPaused?'instant':'smooth'})}});
window.addEventListener('hashchange',()=>{const update=()=>{shell();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true})};if(!motionPaused&&document.startViewTransition)document.startViewTransition(update);else update();});
shell();
